import mongoose from 'mongoose';

const MONGODB_URI = process.env.MONGODB_URI || 'mongodb://localhost:27017/service_center_db';

let cached = global.mongoose;

if (!cached) {
  cached = global.mongoose = { conn: null, promise: null, isConnected: false };
}

export async function connectToDatabase() {
  if (cached.conn) {
    cached.isConnected = mongoose.connection.readyState === 1;
    return cached.conn;
  }

  if (!cached.promise) {
    const opts = {
      bufferCommands: false,
      serverSelectionTimeoutMS: 2000,
    };

    cached.promise = mongoose.connect(MONGODB_URI, opts)
      .then((mongooseInstance) => {
        cached.isConnected = true;
        console.log('[MongoDB] Connected successfully');
        return mongooseInstance;
      })
      .catch((err) => {
        cached.promise = null;
        cached.isConnected = false;
        console.log('[MongoDB] Note: Local/Remote MongoDB not responding (using standby memory mode):', err.message);
        return null;
      });
  }

  try {
    cached.conn = await cached.promise;
    cached.isConnected = mongoose.connection.readyState === 1;
  } catch (e) {
    cached.promise = null;
    cached.conn = null;
    cached.isConnected = false;
  }

  return cached.conn;
}

export function isDbConnected() {
  return mongoose.connection.readyState === 1;
}
